from sglang.srt.debug_utils.comparator.unshard.types import AxisInfo

_PARALLEL_INFO_KEYS = ("sglang_parallel_info", "megatron_parallel_info")

# Maps a parallel axis to the field-name prefix used inside the parallel_info dict,
# e.g. ParallelAxis.TP -> "tp" for the "tp_rank" / "tp_size" fields.
_AXIS_FIELD_PREFIXES = {
    ParallelAxis.TP: "tp",
    ParallelAxis.CP: "cp",
}


def normalize_parallel_info(meta: dict) -> dict[ParallelAxis, AxisInfo]:
    present_keys = [key for key in _PARALLEL_INFO_KEYS if key in meta]
    if len(present_keys) > 1:
        raise ValueError(
            f"Found multiple parallel_info keys in meta: {present_keys}"
        )
    if not present_keys:
        return {}

    info = meta[present_keys[0]]

    result: dict[ParallelAxis, AxisInfo] = {}
    for axis, prefix in _AXIS_FIELD_PREFIXES.items():
        rank_key = f"{prefix}_rank"
        size_key = f"{prefix}_size"
        if rank_key not in info or size_key not in info:
            continue
        axis_size = int(info[size_key])
        if axis_size == 1:
            continue
        result[axis] = AxisInfo(axis_rank=int(info[rank_key]), axis_size=axis_size)
    return result
