from sglang.srt.debug_utils.comparator.dims import DimSpec, ParallelAxis
from sglang.srt.debug_utils.comparator.unshard.types import (
    AxisInfo,
    UnshardParams,
    UnshardPlan,
)


def compute_unshard_plan(
    dim_specs: list[DimSpec],
    parallel_infos: list[dict[ParallelAxis, AxisInfo]],
) -> Optional[UnshardPlan]:
    sharded_dims = [
        (index, spec.parallel)
        for index, spec in enumerate(dim_specs)
        if spec.parallel is not None
    ]
    if not sharded_dims:
        return None

    distinct_axes = {axis for _, axis in sharded_dims}
    if len(distinct_axes) > 1:
        raise NotImplementedError(
            f"Multi-axis unshard is not supported: "
            f"axes={sorted(axis.value for axis in distinct_axes)}"
        )

    if not parallel_infos:
        raise ValueError("parallel_infos must not be empty")

    dim_index, axis = sharded_dims[0]

    axis_size: Optional[int] = None
    world_rank_by_axis_rank: dict[int, int] = {}
    for world_rank, info in enumerate(parallel_infos):
        axis_info = info.get(axis)
        if axis_info is None:
            continue
        if axis_size is None:
            axis_size = axis_info.axis_size
        elif axis_size != axis_info.axis_size:
            raise ValueError(
                f"Inconsistent axis_size for {axis}: "
                f"{axis_size} vs {axis_info.axis_size}"
            )
        world_rank_by_axis_rank[axis_info.axis_rank] = world_rank

    if axis_size is None:
        raise ValueError(f"No parallel_info found for axis {axis}")

    world_ranks_by_axis_rank = [
        world_rank_by_axis_rank[axis_rank] for axis_rank in range(axis_size)
    ]

    return UnshardPlan(
        axis=axis,
        params=UnshardParams(dim=dim_index),
        world_ranks_by_axis_rank=world_ranks_by_axis_rank,
    )
