from sglang.srt.debug_utils.comparator.unshard.types import UnshardPlan


def execute_unshard_plan(
    plan: UnshardPlan,
    tensors_by_world_rank: dict[int, torch.Tensor],
) -> torch.Tensor:
    ordered_shards = [
        tensors_by_world_rank[world_rank]
        for world_rank in plan.world_ranks_by_axis_rank
    ]
    return torch.cat(ordered_shards, dim=plan.params.dim)
